INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10927, 78033, 'tt0093944', NULL, 'My Heart Is That Eternal Rose', '殺手蝴蝶夢', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/igW5rfwv0BBMu3ogmbjxUMQxm6q.jpg', 'https://image.tmdb.org/t/p/original/qnNGXmLZ147lMnUjfnTRmjfteBG.jpg', 'The fallout resulting from a botched Triad gang smuggling job forces a young couple to separate - she becomes a kingpin’s unwilling moll and he travels to the Philippines to work as a contract killer. Six years later, the two are reunited in a chance encounter, but their rekindled emotions and people from their past lead them into extreme danger.', NULL, NULL, 1.5138, 7.3, 0, 9.52, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10928, 298972, 'tt0125549', NULL, 'The Island Closest to Heaven', '天国にいちばん近い島', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/ctepLZAMh3HCJo4n5zfHbzsvUX5.jpg', 'https://image.tmdb.org/t/p/original/kJsAkDZ8mMDeYxqnFpnStzN2fLs.jpg', 'A Japanese teenager travels to New Caledonia in search of the fabled "island closest to heaven" that her late father had told her about.', NULL, NULL, 0.7684, 6.333, 0, 9.52, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10929, 38954, 'tt0097067', NULL, 'City Hunter: .357 Magnum', 'シティーハンター 愛と宿命のマグナム', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/sxn56IEAsAxnaNYEMGCfIP0aNkT.jpg', 'https://image.tmdb.org/t/p/original/lKgtOPVjqHScgGLjnRYT1MX6Cax.jpg', 'A beautiful pianist comes to Tokyo for a charity concert - and City Hunter is there. But music isn''t his forte. He wants lessons in the language of love. Desperation is the word as bodies start dropping. A foreign dignitary is assassinated in cold blood. Secret agents scour the streets for a missing microchip. And diplomatic infighting swirls around the upcoming concert until Nina the pianist and her grandfather Klaus are kidnapped. A maelstrom of exploding grenades, the rumble of Falcon''s jeep, and the tinkling of the ivories all set the stage for City Hunter: . 357 Magnum. The show must go on!', NULL, NULL, 1.3485, 6.435, 0, 10.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10930, 17922, 'tt0086148', NULL, 'Golgo 13: The Professional', 'ゴルゴ13', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/nOTFmar2FyhDEDFNIMQL97K5Pcg.jpg', 'https://image.tmdb.org/t/p/original/yH36l9jTeeY69clGiPgtORQRZnG.jpg', 'Indestructible to his enemies and irresistible to women, the professional assassin codenamed Golgo 13 is shrouded in mystery and anonymity. If you''re on his hit list, you''re already dead. Always hired on his reputation alone, Golgo never breaks a contract. Can he survive the combined forces of the FBI, CIA, the Pentagon and the U.S. Army? Has the nameless agent finally met his match against the superhuman powers of the Snake and the twin evils of the psychopathic mercenaries, Gold and Silver?', NULL, NULL, 1.9148, 6.2, 0, 10.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10931, 1369064, 'tt15307512', NULL, 'A Christmas in New Hope', 'A Christmas in New Hope', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/niHnCfIixaga9Ux9BKfHTbvpry1.jpg', 'https://image.tmdb.org/t/p/original/6jXIe1AFMNwC3bH1rT0XoPMuRkE.jpg', 'To save her bungalow from foreclosure before Christmas, Victoria, an Instagram influencer and single mother of a child living with Down syndrome enters a home-improvement competition in New Hope, Texas. Complications arise when her ex returns home after touring Europe with his new album. Meanwhile, Victoria has fallen in love with her next-door neighbor, Gavin, a Texas musician who has bonded with her daughter Charlie while helping Victoria fix up her home, as well as her heart.', NULL, NULL, 0.6164, 6.3, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10932, 314810, 'tt0083317', NULL, 'We''re Fighting Back', 'We''re Fighting Back', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/safOrqrpszMyf0UiFBaphyiRbzp.jpg', NULL, 'Inspired by the exploits of New York''s Guardian Angels, which began as a band of streetwise young people who formed an anti-crime subway patrol and went on to gain a national reputation and units in major cities around the country, this film unites three New York City youths as leaders of a citizens'' patrol tackling gangs terrorizing merchants and local citizens.', NULL, NULL, 0.5308, 7.0, 0, 2.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
