INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10942, 1921, 'tt0230838', NULL, 'Sweet November', 'Sweet November', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/3biEHZSBSYqSkawU2sQyNbLcjgE.jpg', 'https://image.tmdb.org/t/p/original/6KfQTuw4X3LQN11sDA18eYy9HJY.jpg', 'Nelson is a man devoted to his advertising career in San Francisco. One day, while taking a driving test at the DMV, he meets Sara. She is very different from the other women in his life. Nelson causes her to miss out on taking the test and later that day she tracks him down. One thing leads to another and Nelson ends up living with her through a November that will change his life forever.', NULL, NULL, 4.907, 6.868, 0, 6.53, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
