INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10945, 10337, 'tt0101516', NULL, 'Bugsy', 'Bugsy', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/hSGncpMByW8zx2aOSXdZB0e70yA.jpg', 'https://image.tmdb.org/t/p/original/t353Hj5sFXWQFriVzB1GiT3TSlm.jpg', 'New York gangster Ben ''Bugsy'' Siegel takes a brief business trip to Los Angeles. A sharp-dressing womanizer with a foul temper, Siegel doesn''t hesitate to kill or maim anyone crossing him. In L.A. the life, the movies, and most of all strong-willed Virginia Hill detain him while his family wait back home. Then a trip to a run-down gambling joint at a spot in the desert known as Las Vegas gives him his big idea.', NULL, NULL, 3.8791, 6.346, 0, 5.51, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
