INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10966, 27359, 'tt0443455', NULL, 'Brand Upon the Brain!', 'Brand Upon the Brain!', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/aCnZaP8QUUYrqoMoE9JOkvUOvQd.jpg', 'https://image.tmdb.org/t/p/original/e6VVxwmW6RMnBU9nV2xVPpjB6RR.jpg', 'After returning home to his long-estranged mother upon a request from her deathbed, a man raised by his parents in an orphanage has to confront the childhood memories that have long haunted him.', NULL, NULL, 1.2038, 6.6, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10967, 161459, 'tt0267703', NULL, 'Maidan-E-Jung', 'Maidan-E-Jung', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/i0kecYaFA4Rg9WfXriM4sj69kns.jpg', 'https://image.tmdb.org/t/p/original/xHBTIgw2FE48ObgrBQ3JC5lPLDH.jpg', 'Daata Guru (Amrish Puri) is a wealthy, powerful, and influential head of a village. He owns and controls all the villagers and their properties. Anyone who dares to raise their voice against him is crushed by his employee, Shankar (Dharmendra), and his sons, Guman (Gulshan Grover) and Karan (Akshay Kumar). When Daata Guru learns that Shankar has abducted his widowed daughter-in-law, Lakhsmi (Jaya Pradha), and has married her, he is enraged and wants Shankar dead. Daata Guru also instigates Karan against Shankar, and threatens the villagers to cut off their water supply if they do not turn in Shankar to him. What will Shankar do to protect his new wife and himself from the wrath of Daata Guru and his men?', NULL, NULL, 0.871, 6.667, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10968, 29146, 'tt0062794', NULL, 'Charly', 'Charly', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/uxGt80D4hxEEwGwdOJ5tdVvjXEC.jpg', 'https://image.tmdb.org/t/p/original/sURKVV4auOpRWaS6lRIdcTPtlee.jpg', 'An experiment on a simpleton turns him into a genius. When he discovers what has been done to him he struggles with whether or not what was done to him was right.', NULL, NULL, 1.2163, 6.455, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
