INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10971, 77551, 'tt0451154', NULL, 'The Passing', 'The Passing', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/ieXjXRLoOLXg2WmvByzaXtwbbVt.jpg', NULL, 'The three Naibert children, in their teens and early twenties, inherit a vast estate from their grandmother Rebecca. But unknown to them, the family inheritance has passed from grandmother to granddaughter for centuries-and Rebecca has a long reach from the grave to assure that the line is unbroken. The first weekend in the mansion is a party for the three Naiberts and their friends-but one by one, they vanish without a trace. Is death the punishment for violating Rebecca''s spell? Are the demons that beset the young people real-or only reflections of their own fear? Is it murder, violence from another dimension, or madness? The answer lives in the reflections.', NULL, NULL, 0.5278, 3.125, 0, 1.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
