INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10982, 30698, 'tt0400435', NULL, 'The Five People You Meet In Heaven', 'The Five People You Meet In Heaven', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/1fvMz3gy4YuqPDC5LotTWofFFcx.jpg', 'https://image.tmdb.org/t/p/original/llZz64BIZcIyGnazveysBCFsPsN.jpg', 'On his 83rd birthday, Eddie, a war vet and a maintenance worker at the Ruby Pier amusement park, dies while trying to save a girl who is sitting under a falling ride. When he awakens in the afterlife, he encounters five people with ties to his corporeal existence who help him understand the meaning of his life.', NULL, NULL, 1.442, 6.986, 0, 1.03, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10983, 10670, 'tt0076636', NULL, 'Rollercoaster', 'Rollercoaster', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/dy23SSGZDp3dftzhDvHXOEM6OaN.jpg', 'https://image.tmdb.org/t/p/original/pXUs9wl6jyTdarMLVcQ00pPhEPt.jpg', 'A young terrorist kills and injures patrons of a Norfolk amusement park by placing homemade explosives on the track of one of its roller coasters. After staging a similar incident in Pittsburgh, he sends a tape to a meeting of major amusement park executives in Chicago, demanding $1 million to make him stop.', NULL, NULL, 1.2282, 6.006, 0, 1.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10984, 462293, NULL, NULL, 'Powerwolf @ Hellfest', 'Powerwolf @ Hellfest', 'movie', 2017, NULL, NULL, 'In 2017, it was impossible to qualify the members of Powerwolf as young Cubs. Indeed, the group now enjoys a solid reputation, in studio as in album. A recognition gained thanks to a great regularity of writing and particularly entertaining shows. Faced with this success, some critics even see in Powerwolf the future of heavy metal.', NULL, NULL, 1.2231, 10.0, 0, 2.06, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10985, 24548, 'tt0089393', NULL, 'Just One of the Guys', 'Just One of the Guys', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/7ffvsRv8ueYYK0H3zocmNRPd8yN.jpg', 'https://image.tmdb.org/t/p/original/wXYv3mC6mZPVChHBMxF2tVILcLb.jpg', 'When Terry Griffith loses her high school''s writing competition, she''s convinced that it''s because she''s a girl. So Terry decides to change high schools and pose as a boy to prove her point. Her brother, Buddy, helps her pass as a guy so well that she is soon making friends with the boys at school, including the attractive Rick, who becomes her new best friend. But her gender-swapping makes things difficult when she falls in love with him.', NULL, NULL, 3.3244, 6.429, 0, 8.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10986, 187017, 'tt2294449', NULL, '22 Jump Street', '22 Jump Street', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/850chzYHYbT3IISl6Q7dbBuFP2B.jpg', 'https://image.tmdb.org/t/p/original/kdyYOwpKvvD2fSbwfnMM2YPAzfq.jpg', 'After making their way through high school (twice), big changes are in store for officers Schmidt and Jenko when they go deep undercover at a local college. But when Jenko meets a kindred spirit on the football team, and Schmidt infiltrates the bohemian art major scene, they begin to question their partnership. Now they don''t have to just crack the case - they have to figure out if they can have a mature relationship. If these two overgrown adolescents can grow from freshmen into real men, college might be the best thing that ever happened to them.', NULL, NULL, 12.4785, 6.826, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10987, NULL, NULL, 9643, 'Return of the Obra Dinn', 'Return of the Obra Dinn', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27j9.jpg', NULL, 'In this 1-bit first-person mystery game, a merchant ship called the Obra Dinn has appeared at a London harbor, years after being declared lost at sea. As an insurance adjuster, the player must examine the ship for clues.', 'https://www.igdb.com/games/return-of-the-obra-dinn', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 9.51, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10988, 554917, 'tt7144200', NULL, 'The Siren', 'The Siren', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/qR1Yf8e8EkmGwO0txvecCyw0PD.jpg', 'https://image.tmdb.org/t/p/original/esNKqrOc39Nye3fUfh96peW65Kg.jpg', 'Tom, a mute man is on retreat to an isolated lakehouse where he meets Al, who is mourning the recent death of his husband. Starting off rather friendly, Tom and Al’s rapport slowly changes as the former befriends a mysterious woman named Nina, for whom Al can’t shake his negative suspicions.', NULL, NULL, 1.5489, 5.452, 0, 9.52, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10989, 71886, 'tt5615700', NULL, 'Siren', 'Siren', 'tv', 2018, 'https://image.tmdb.org/t/p/w500/k906XXqqFMT93v2WMkIOtUcEAlV.jpg', 'https://image.tmdb.org/t/p/original/nMVuvboq4tSM22dkZb7ekQi9WKS.jpg', 'The coastal town of Bristol Cove is known for its legend of once being home to mermaids. When the arrival of a mysterious girl proves this folklore all too true, the battle between man and sea takes a very vicious turn as these predatory beings return to reclaim their right to the ocean.', NULL, NULL, 13.4249, 7.738, 0, 8.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10990, 157409, 'tt2332579', NULL, 'Crystal Fairy & the Magical Cactus', 'Crystal Fairy y el cactus mágico', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/jX34ccG13P66S4qVqLRRyR0hZLS.jpg', 'https://image.tmdb.org/t/p/original/peH8u8aGZlvMXQXI7HwzE2F76Sj.jpg', 'Jamie is a boorish, insensitive American twentysomething traveling in Chile, who somehow manages to create chaos at every turn. He and his friends are planning on taking a road trip north to experience a legendary shamanistic hallucinogen called the San Pedro cactus. In a fit of drunkenness at a wild party, Jamie invites an eccentric woman—a radical spirit named Crystal Fairy—to come along.', NULL, NULL, 0.8198, 5.939, 0, 2.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10991, 519198, 'tt10855784', NULL, 'Double Labyrinthe', 'Double Labyrinthe', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/kfci1WIyJ8m0ymWa7REPzUgtzhE.jpg', 'https://image.tmdb.org/t/p/original/8CAd0uyD4dIKSW9TYfouakBA48m.jpg', 'With this film-manifesto, the two artists invent what they called the Cinéma corporel (Cinema of the Body), they present themselves as a "double auteur femme" and they lay the foundations of the radical critical and esthetical positions of their work to come. Double Labyrinthe has a mirror structure based on their "mutual gaze": in the first part Katerina performs while filmed by Maria and in the second part Maria performs filmed by Katerina.', NULL, NULL, 0.7117, 6.5, 0, 1.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10992, 36877, 'tt0021331', NULL, 'The Blood of a Poet', 'Le Sang d''un poète', 'movie', 1932, 'https://image.tmdb.org/t/p/w500/paHmfMrtQVT2cUTeteni3iDgRym.jpg', 'https://image.tmdb.org/t/p/original/kRQVehqORmZPeK3kt7ktmeKPhqt.jpg', 'In a poet’s room, an armless statue abruptly comes to life. It invites the poet to step through a mirror and to discover another world. Strange places and characters present themselves to him. The poet tears himself away from these twisted fascinations and returns, with some difficulty, to his room.', NULL, NULL, 1.3569, 7.042, 0, 1.02, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10993, 11878, 'tt0055630', NULL, 'Yojimbo', '用心棒', 'movie', 1961, 'https://image.tmdb.org/t/p/w500/tN7kYPjRhDolpui9sc9Eq9n5b2O.jpg', 'https://image.tmdb.org/t/p/original/5BBwSVytssbFuSPZE4DtJVhROjN.jpg', 'A nameless ronin, or samurai with no master, enters a small village in feudal Japan where two rival businessmen are struggling for control of the local gambling trade. Taking the name Sanjuro Kuwabatake, the ronin convinces both silk merchant Tazaemon and sake merchant Tokuemon to hire him as a personal bodyguard, then artfully sets in motion a full-scale gang war between the two ambitious and unscrupulous men.', NULL, NULL, 5.6311, 8.08, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
