INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10995, 486832, 'tt7313348', NULL, 'Them That Follow', 'Them That Follow', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/y5pXzgds0pPOJevmunFkPFMaaGU.jpg', 'https://image.tmdb.org/t/p/original/hdjeh4ZU4Ifo9yAJwM9d3JqqCaS.jpg', 'A Pentecostal pastor, Lemuel Childs, and his believers handle venomous snakes to prove themselves before God. Lemuel’s daughter, Mara holds a secret that threatens to tear the church apart: her romantic past with a nonbeliever, Augie. As Mara’s wedding to a devoted follower looms, she must decide whether or not to trust the steely matriarch of their community, Hope, with her heart and life at stake.', NULL, NULL, 3.2246, 4.957, 0, 9.55, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
