INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11015, 63020, 'tt0114113', NULL, 'The Perez Family', 'The Perez Family', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/jxi3UDHf86kDk5hqJxnpEMzVch2.jpg', 'https://image.tmdb.org/t/p/original/34O2EvrVTUup7a0JllQWtXURQw1.jpg', 'In the midst of the Mariel boat lift -- a hurried exodus of refugees from Cuba going to America -- an immigration clerk accidentally presumes that dissident Juan Raul Perez and Dorita Evita Perez are married. United by their last name and a mutual resolve to emigrate, Dorita and Juan agree to play along. But it gets complicated when the two begin falling for each other just as Juan reunites with his wife, Carmela, whom he hasn''t seen in decades.', NULL, NULL, 1.7578, 6.119, 0, 8.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11016, 74726, 'tt1838571', NULL, 'Juan of the Dead', 'Juan de los muertos', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/yQLHnDXOdl2gny6glOsts3Btczc.jpg', 'https://image.tmdb.org/t/p/original/qlKK49jNOK9a3DhDbWKoB8hA5Vn.jpg', 'While Havana is full of zombies hungry for human flesh, official media reported that the disturbances are caused by dissidents paid by the United States. Panic seizes all until Juan comes to the rescue: he discovers he can kill the undead destroying his brain, and decides to start a small business under the slogan "We kill your loved ones."', NULL, NULL, 1.2839, 6.243, 0, 10.52, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
