INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11031, 536097, 'tt8707622', NULL, 'Rogue Trooper', 'Rogue Trooper', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/dckqO4JsRUCDEwUU5syW6v67WEc.jpg', 'https://image.tmdb.org/t/p/original/7NWYrpQ5NPz6Xiv6CkCozPUx96n.jpg', 'Rogue is a "Genetic Infantryman", a genetically-engineered, blue-skinned, manufactured super soldier who, alongside his three comrades, is searching for the Traitor General. His comrades are with him in the form of biochips—onto which a G.I.''s entire personality is downloaded at the time of death for later retrieval—and are named Gunnar (mounted on Rogue''s rifle), Bagman (on his backpack) and Helm (on his helmet). Rogue is designed to be immune to almost all known toxins, can submerge in strong acid unaffected, and is able to withstand a vacuum on his bare skin.', NULL, NULL, 1.7421, 7.0, 0, 9.015, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
