INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11041, 85273, 'tt5194792', NULL, 'NOS4A2', 'NOS4A2', 'tv', 2019, 'https://image.tmdb.org/t/p/w500/gnosVTTRTCqooJuipwU6C0bgOGf.jpg', 'https://image.tmdb.org/t/p/original/enRS7bE43q7VmurYqlyroOeZLGa.jpg', 'A young Victoria "Vic" McQueen discovers she has the power to unlock portals that help her find lost objects. As she delves further into this hidden universe, she encounters many other "inscape travelers" - some benevolent, and some who have been corrupted by their power. When Vic encounters Charlie Manx, an immortal who stays that way by feeding off of the souls of children, she makes a sworn enemy of Manx.', NULL, NULL, 7.3063, 7.281, 0, 9.51, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
