INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11066, 9319, 'tt0102266', NULL, 'The Last Boy Scout', 'The Last Boy Scout', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/glPswihcZYoAQ4YM2uJF4UACy8T.jpg', 'https://image.tmdb.org/t/p/original/8AZ8Hjcr4Jr1eR93OW70g9jjUr9.jpg', 'Somewhere in Los Angeles, the city of broken dreams, a stripper is murdered. Now, the private detective she had hired and her ex-footballer boyfriend are going to find her murderer... if they don''t kill each other first. But the more they dig, the deeper they become enmeshed in a web of extortion, blackmail and corrupt politics hidden beneath the surface of professional football.', NULL, NULL, 7.0215, 6.844, 0, 10.03, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11067, 23449, 'tt0115851', NULL, 'Celtic Pride', 'Celtic Pride', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/5P3p9I2ADnTbBdIAl4ZUeUXGuIi.jpg', 'https://image.tmdb.org/t/p/original/90VhKNMbZpv3VvcFWsYywM1pVlk.jpg', 'Two over-loyal Celtic fans kidnap their opponent''s star player in order to guarantee their team the championship.', NULL, NULL, 1.4956, 5.316, 0, 10.05, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
