INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11077, 109125, 'tt1788453', NULL, 'The Amazing Bulk', 'The Amazing Bulk', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/mClp6KhHY42iDQIC5Spha8ozbvr.jpg', 'https://image.tmdb.org/t/p/original/6gXEchOPnTARjMREp6WJPIp9ECF.jpg', 'Henry Howard, an ambitious young scientist struggles to develop a super human serum designed to improve muscle mass and prolong life expectancy. His boss, the grumpy General Darwin, will not allow Hank to marry his daughter, Hannah, until the experiment is a success. Against Darwin''s wishes Hank proposes to Hannah anyway, but his life is shattered by a mugger who steals his engagement ring. Dejected, Hank injects himself with the experimental serum and is transformed into the Amazing Bulk. The Bulk goes on a rampage through the city destroying everything in his path. Hank is caught by a relentless detective, imprisoned by Darwin and forced to battle the sadistic Dr. Kantlove, who threatens to blow up the moon with his arsenal of weapons.', NULL, NULL, 0.9448, 2.481, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
