INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11080, 33247, 'tt0104745', NULL, 'The Living End', 'The Living End', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/4tqdQcKkZGn4qQy9bWWu1fEM6z2.jpg', 'https://image.tmdb.org/t/p/original/5x7oNRmIyYiTcmaXfHUBajZf2jy.jpg', 'Two HIV-positive young men — a semi-employed film critic and a hot hustler — tear off on a cross-country crime spree.', NULL, NULL, 1.7296, 6.7, 0, 1.10100000000000015e+01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11081, 217048, 'tt0052125', NULL, 'Eine Reise ins Glück', 'Eine Reise ins Glück', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/zRTWKROCDMUXwEUOlMt7Ny6HyJK.jpg', NULL, 'Together with her uncle and waiter Otto, young Renate runs a guesthouse high above the Rhine, which hardly any guests ever visit. When she suddenly inherits a vineyard in Tuscany one day, the three of them set off full of hope on the arduous journey south. However, the inheritance turns out to be a dilapidated estate, whose valuable wines stored in a secret cellar are known only to the devious wine merchant Brandolini. Fortunately, he has a nice brother who falls in love with Renate and helps her out.', NULL, NULL, 0.7383, 6.5, 0, 7.51, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11082, 347085, 'tt9881774', NULL, 'Jan Švankmajer: The Complete Short Films', 'Jan Švankmajer: The Complete Short Films', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/Khe9H6YuhnZZfu1sNDP3puL9nw.jpg', 'https://image.tmdb.org/t/p/original/p42nJVuMSwCuZDwrbzWTSxz279d.jpg', 'Featuring all 26 entries in the official filmography, this is the world''s first complete DVD edition of the short films by the legendary Czech Surrealist filmmaker-animator Jan Švankmajer. Technically and conceptually astonishing in their own right, these films are also as remarkable for their philosophical consistency as for their frequently mind-boggling imagery. This package also includes a bonus short, Johanes Doktor Faust (1958), the longer cut of ''The Cabinet of Jan Švankmajer'' with a new introduction by the Quay Brothers, the documentary Les Chimeres des Švankmajer (2001), interviews with Jan and Eva Švankmajer and examples of their work in other media. There''s also a chance to see some Švankmajer special effects, created when he was banned from directing his own films.', NULL, NULL, 0.4776, 10.0, 0, 7.51, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
