INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11119, 17264, 'tt0078872', NULL, 'The Black Stallion', 'The Black Stallion', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/uZtNc31LR5Ik3ZVo2jxwOvhkNRC.jpg', 'https://image.tmdb.org/t/p/original/am84QBW5S17uKUeuWvjLIS8urrr.jpg', 'While traveling with his father, young Alec becomes fascinated by a mysterious Arabian stallion that is brought on board and stabled in the ship he is sailing on. When it tragically sinks both he and the horse survive only to be stranded on a deserted island. He befriends it, so when finally rescued both return to his home where they soon meet Henry Dailey, a once successful trainer. Together they begin training the horse to race against the fastest ones in the world.', NULL, NULL, 5.99, 7.047, 0, 10.51, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
