INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11152, 949113, NULL, NULL, 'Tzouhalem', 'Tzouhalem', 'movie', 2021, NULL, NULL, 'Through interviews and creative re-enactments, this documentary examines the near-mythic figure of Cowichan Chief Tzouhalem, the account of his life from both historians and First Nations Elders, the folkloric tales concerning him, his impact on the modern relationship between the Crown and First Nations, and how his legend remains alive to this day, examining critically how his storv has been told and passed down to us.', NULL, NULL, 0.7392, 0.0, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11153, 252501, 'tt0107445', NULL, 'The Lotus Eaters', 'The Lotus Eaters', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/zyMy0PCnfB8BIX0fJzgc8qaPT0w.jpg', 'https://image.tmdb.org/t/p/original/onxkupO1JC22Nbp7ZiKeEDeBkvm.jpg', 'Set off the West Coast of Canada in 1965, a hip new teacher with a miniskirt and lots of ideas turns a small town upside down.  The soft autumn light of Galiano Island is beautifully rendered in writer/producer Peggy Thompson''s The Lotus Eaters, and that''s not the only elusive element that this film has captured.  In revisiting its particular time and place - the Gulf Islands of the early ''60s -Thompson obviously draws on her own family experiences there.  For those who share Thompson''s love of Gulf Islands magic, the elements she has assembled will feel as familiar as their own childhood blanket.  But there are problems at the core of this story about a family''s loss of innocence.', NULL, NULL, 0.6768, 8.5, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
