INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11176, 1273033, NULL, NULL, 'Liverpool. The Blue and Yellow Submarine', 'Ліверпуль. Жовто-блакитна субмарина', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/m2Z2yaDsRybBIhcwqBJpXafPM1c.jpg', 'https://image.tmdb.org/t/p/original/rSiZllYQdijuqSGcRJ8A4Le1oGp.jpg', 'A documentary project that shows viewers behind the scenes of this cultural exchange and explores the current processes of integrating Ukrainian culture into the European context.  The heroes of the project are the participants and visitors of the festival, who demonstrate with their own stories the unique connection and cultural integration of Ukraine into the plane of Liverpool, one of the cultural capitals of Europe. In particular, Sarah Fisher, director of Liverpool''s Open eye gallery, Yuliia Kurinna, a volunteer and displaced person from Nova Kakhovka, and actor and director Yurii Radionov will share their thoughts.', NULL, NULL, 0.2994, 0.0, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
