INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11190, 41966, 'tt0095871', NULL, 'Pin : A Plastic Nightmare', 'Pin : A Plastic Nightmare', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/ouUfJtdHPkRXFJ0zDLPvgbPHPjd.jpg', 'https://image.tmdb.org/t/p/original/yDuhznnNmR4Pehf9QubGnLkEBNC.jpg', 'Pin, a plastic medical dummy, has been the fixation of Leon since youth. Now grown up and orphaned in an accident, Leon brings Pin home to live with him and his sister Ursula, much to her reluctance. Soon, however, Leon''s fixation on Pin spirals out of control, and Ursula must face the devastating consequences.', NULL, NULL, 1.6541, 6.766, 0, 10.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11191, 44472, 'tt2242025', NULL, 'Hotel Hell', 'Hotel Hell', 'tv', 2012, 'https://image.tmdb.org/t/p/w500/7k88tKxgDpMuJWx7RDIBg5bk5N0.jpg', 'https://image.tmdb.org/t/p/original/uUyul3Prvu31Sr6Tz8tyXZxzwwy.jpg', 'Chef Gordon Ramsay, along with a team of hospitality experts, travels the country applying his high standards to struggling hotels, motels, and bed and breakfasts in an effort to get the owners and staff to turn their establishments around. Ramsay''s signature no-holds-barred style will make it clear to those he coaches that there is no place for dirty rooms or incompetent staff if one hopes to remain in business.', NULL, NULL, 2.6016, 6.759, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11192, 17379, 'tt0408985', NULL, 'Last Holiday', 'Last Holiday', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/2SkM1AHIgCQgdOboER6euPKTxGF.jpg', 'https://image.tmdb.org/t/p/original/7D1v3y0RPoyJBZAx4eGdjcqJUuD.jpg', 'The discovery that she has a terminal illness prompts introverted department store saleswoman Georgia Byrd to reflect on what she realizes has been an overly cautious life. With weeks to live, she withdraws her life savings, sells all her possessions and jets off to Europe where she lives it up at a posh hotel. Upbeat and passionate, Georgia charms everybody she meets, including renowned Chef Didier. The only one missing from her new life is her longtime crush Sean Williams.', NULL, NULL, 7.0729, 7.272, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11193, 5, 'tt0113101', NULL, 'Four Rooms', 'Four Rooms', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/75aHn1NOYXh4M7L5shoeQ6NGykP.jpg', 'https://image.tmdb.org/t/p/original/c1BaOxC8bo5ACFYkYYxL0bBWRaq.jpg', 'It''s Ted the Bellhop''s first night on the job...and the hotel''s very unusual guests are about to place him in some outrageous predicaments. It seems that this evening''s room service is serving up one unbelievable happening after another.', NULL, NULL, 5.3179, 5.912, 0, 2.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11194, 36109, 'tt5489690', NULL, 'Paradise Hotel', 'Paradise Hotel', 'tv', 2009, 'https://image.tmdb.org/t/p/w500/k6KhQBpW4gdcoSp9JQvQFq14lFI.jpg', 'https://image.tmdb.org/t/p/original/naUighMJIjHGQJIXSj7wMOgKbSd.jpg', 'Norwegian girls and boys check in at the Paradise Hotel in Mexico, where Triana Iglesias is the hotel manager. The hotel has great views and a fantastic pool. Cameras with a full view of the idyllic site tells the story of what happens when the single boys and girls meet in the hot surroundings of the hotel. The task they have is basically simple: Find a partner or check out.', NULL, NULL, 143.8229, 5.7, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
