INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11196, 3004, 'tt0083455', NULL, 'Newhart', 'Newhart', 'tv', 1982, 'https://image.tmdb.org/t/p/w500/zBI5YcdsftGE9F6zY6UwYVybsdY.jpg', 'https://image.tmdb.org/t/p/original/pCUfyiLZ1bT7JkffXZdDT0PgbGz.jpg', 'Dick Loudon and his wife Joanna decide to leave life in New York City and buy a little inn in Vermont. Dick is a how-to book writer, who eventually becomes a local TV celebrity as host of "Vermont Today." George Utley is the handyman at the inn and Leslie Vanderkellen is the maid, with ambitions of being an Olympic Ski champion; she is later replaced by her cousin Stephanie, an heiress who hates her job. Her boyfriend is Dick''s yuppie TV producer, Michael Harris. There are many other quirky characters in this fictional little town, including Dick''s neighbors Larry, Darryl, and Darryl...three brothers who buy the Minuteman Cafe from Kirk Devane. Besides sharing a name, Darryl and Darryl never speak.', NULL, NULL, 33.6229, 7.177, 0, 1.01, '2026-08-21 01:43:43', '2026-08-21 01:43:43');
