UPDATE "recommendations" SET "tmdb_id"=28032, "imdb_id"='tt0111419', "igdb_id"=NULL, "title"='Thumbelina', "original_title"='Thumbelina', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/eBvSSfwAKgcjF4eyaeNSzTCpfaF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jhxmxSNBNCAKtHeJnJhWpkOOI7d.jpg', "overview"='Born of a flower and growing to only a couple of inches tall, poor Thumbelina is worried she''ll never meet someone her own size, until she happens to catch the eye of Prince Cornelius of the Fairies. Just as soon as she finds love, however, it''s torn away when she''s kidnapped by Ms. Toad. Now Thumbelina has to escape Ms. Toad''s grasp and search for Prince Cornelius. Luckily, there''s a whole city of animals willing to help.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3319, "vote_average"=6.466, "is_ambiguous"=0, "evidence_score"=2.27688235294117617e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-21 01:43:43' WHERE "id"=2134;
