UPDATE "recommendations" SET "tmdb_id"=421, "imdb_id"='tt0362270', "igdb_id"=NULL, "title"='The Life Aquatic with Steve Zissou', "original_title"='The Life Aquatic with Steve Zissou', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/qZoFLNBC78jzboWeDH6Ha0qavF2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7tWktnLQ81G8pHUkhuTebcTkcB3.jpg', "overview"='Renowned oceanographer Steve Zissou has sworn vengeance upon the rare shark that devoured a member of his crew. In addition to his regular team, he is joined on his boat by Ned, a man who believes Zissou to be his father, and Jane, a journalist pregnant by a married man. They travel the sea, all too often running into pirates and, perhaps more traumatically, various figures from Zissou''s past, including his estranged wife, Eleanor.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7199, "vote_average"=7.073, "is_ambiguous"=0, "evidence_score"=1.57763636363636354e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-21 01:43:43' WHERE "id"=2491;
UPDATE "recommendations" SET "tmdb_id"=929204, "imdb_id"='tt17163970', "igdb_id"=NULL, "title"='Wallace & Gromit: Vengeance Most Fowl', "original_title"='Wallace & Gromit: Vengeance Most Fowl', "media_type"='movie', "release_year"=2024, "poster_url"='https://image.tmdb.org/t/p/w500/jUWFSBxTOiCinPdTOh3IDUXVemZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/XNVdWNgiAHu8y4BsJv5ndUHXxN.jpg', "overview"='Gromit’s concern that Wallace is becoming too dependent on his inventions proves justified, when Wallace invents a “smart” gnome that seems to develop a mind of its own. When it emerges that a vengeful figure from the past might be masterminding things, it falls to Gromit to battle sinister forces and save his master… or Wallace may never be able to invent again!', "external_url"=NULL, "platforms"=NULL, "popularity"=9.9079, "vote_average"=7.45, "is_ambiguous"=0, "evidence_score"=6.8149999999999995e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-21 01:43:43' WHERE "id"=2509;
