UPDATE "recommendations" SET "tmdb_id"=250574, "imdb_id"='tt2428170', "igdb_id"=NULL, "title"='Creep', "original_title"='Creep', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/qn53D574tT0YRyLgirEFHQwGUXw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/AvrGwToWkP6fp13lzpxsyzoq9JH.jpg', "overview"='Looking for work, Aaron comes across a cryptic online ad: “$1,000 for the day. Filming service. Discretion is appreciated.” Low on cash and full of naiveté, he decides to go for it. He drives to a cabin in a remote mountain town where he meets Josef, his cinematic subject for the day. Josef is sincere and the project seems heartfelt, so Aaron begins to film. But as the day goes on, it becomes clear that Josef is not who he says, and his intentions are not at all pure.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.3603, "vote_average"=6.4, "is_ambiguous"=0, "evidence_score"=3.01411111111111118e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-21 01:43:43' WHERE "id"=3756;
