UPDATE "recommendations" SET "tmdb_id"=145135, "imdb_id"='tt2387433', "igdb_id"=NULL, "title"='Dark Skies', "original_title"='Dark Skies', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/euLgEo2kvuLjYxbfOekWF3l82t6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oLuAgHcYk9UrulfFJCmYfcnvmgB.jpg', "overview"='From the producers of Paranormal Activity, Insidious, and Sinister comes Dark Skies: a supernatural thriller that follows a young family living in the suburbs. As husband and wife Daniel and Lacey Barret witness an escalating series of disturbing events involving their family, their safe and peaceful home quickly unravels. When it becomes clear that the Barret family is being targeted by an unimaginably terrifying and deadly force, Daniel and Lacey take matters in their own hands to solve the mystery of what is after their family.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.3026, "vote_average"=6.361, "is_ambiguous"=0, "evidence_score"=1.38916666666666657e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-21 01:43:43' WHERE "id"=3840;
