UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=495, "title"='Metro 2033', "original_title"='Metro 2033', "media_type"='game', "release_year"=2010, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co1rd6.jpg', "backdrop_url"=NULL, "overview"='Metro 2033 is a first-person shooter with survival horror elements, based on the Russian book of the same name by Dmitry Glukhovsky. Most of the game takes place underground, but several times Artyom will have to venture outside, into the perpetual nuclear winter. Game progression is fairly linear, though areas may be explored more thoroughly for items and ammunition. Setpieces include a few on-rails sequences, missions that involve defending a location from an onslaught of monsters, and others. A few stages can be completed in a stealthy fashion.', "external_url"='https://www.igdb.com/games/metro-2033', "platforms"='["PC (Microsoft Windows)", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=5.505, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-21 01:43:43' WHERE "id"=4418;
