UPDATE "recommendations" SET "tmdb_id"=9429, "imdb_id"='tt0120770', "igdb_id"=NULL, "title"='A Night at the Roxbury', "original_title"='A Night at the Roxbury', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/7oZ5xE4AL4D5EbeQUaoRxahgzJX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ygc5qt7mxtsPljY2W9LAbZWFDGb.jpg', "overview"='Despite being well into adulthood, brothers Doug and Steve Butabi still live at home and work in the flower shop owned by their dad. They exist only to hit on women at discos, though they''re routinely unsuccessful until a chance run-in with Richard Grieco gets them inside the swank Roxbury club. Mistaken for high rollers, they meet their dream women, Vivica and Cambi, and resolve to open a club of their own.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.6218, "vote_average"=6.535, "is_ambiguous"=0, "evidence_score"=9.21, "created_at"='2026-08-12 02:31:31', "updated_at"='2026-08-21 01:43:43' WHERE "id"=9792;
