UPDATE "recommendations" SET "tmdb_id"=50357, "imdb_id"='tt1772240', "igdb_id"=NULL, "title"='Apollo 18', "original_title"='Apollo 18', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/4bLqU6YncqvKETzvPZPPoVrLUYM.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4HAF3vOCHnCwLD2jLS6MN57HQ2n.jpg', "overview"='Officially, Apollo 17 was the last manned mission to the moon. But a year later in 1973, three American astronauts were sent on a secret mission to the moon funded by the US Department of Defense. What you are about to see is the actual footage which the astronauts captured on that mission. While NASA denies its authenticity, others say it''s the real reason we''ve never gone back to the moon.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.1042, "vote_average"=5.3, "is_ambiguous"=0, "evidence_score"=5.67666666666666586e+00, "created_at"='2026-08-12 02:31:31', "updated_at"='2026-08-21 01:43:43' WHERE "id"=9811;
